type FetchState<
  TSuccess,
  TError = string
> =
  | { kind: 'idle' }
  | { kind: 'loading' }
  | { kind: 'success'; data: TSuccess }
  | { kind: 'error'; error: TError };

function UserCard({ state }: { state: FetchState<User> }) {
  switch (state.kind) {
    case 'idle':
      return <p>Search for a user.</p>;
    case 'loading':
      return <Spinner />;
    case 'success':
      return <Profile user={state.data} />;
    case 'error':
      return <Alert message={state.error} />;
  }
}

type FormState<
  TData,
  TError = string
> =
  | { status: 'idle' }
  | { status: 'submitting' }
  | { status: 'success'; data: TData }
  | { status: 'error'; error: TError };

